    last = max(bars)
    marker_cols = []
    for c in range(w):
        rr = [r for r in range(last + 1, h) if g[r][c]]
        if rr:
            marker_cols.append((c, rr[0], g[rr[0]][c]))

    for c, start, lower_color in marker_cols:
        # At each bar row, the crossing column takes the color of that row's
        # horizontal object, found from the nearest nonzero cell.
        crossings = []
        for r in bars:
            color = g[r][c]
            if not color:
                color = next((g[r][x] for x in range(c - 1, -1, -1) if g[r][x]), 0)
                if not color:
                    color = next((g[r][x] for x in range(c + 1, w) if g[r][x]), 0)
            if color:
                crossings.append((r, color))

        # Extend each crossing color from the prior bar through its row.
        prev = 0
